const encoder = new TextEncoder();

function csv(value: string): Uint8Array {
  return encoder.encode(value);
}

const executionHeaders = [
  "ClientAccountID",
  "AssetClass",
  "Symbol",
  "UnderlyingSymbol",
  "Conid",
  "CurrencyPrimary",
  "TradeDate",
  "DateTime",
  "Quantity",
  "TradePrice",
  "Proceeds",
  "IBCommission",
  "NetCash",
  "FifoPnlRealized",
  "Notes/Codes",
  "IBOrderID",
  "BrokerageOrderID",
  "IBExecID",
  "TradeID",
  "Expiry",
  "Strike",
  "Put/Call",
  "Multiplier",
  "LevelOfDetail",
  "OpenDateTime",
] as const;

type Header = (typeof executionHeaders)[number];
type Fields = Partial<Record<Header | "PositionActionID", string>>;

function row(headers: readonly string[], fields: Fields): string {
  return headers.map((header) => fields[header as Header] ?? "").join(",");
}

function table(headers: readonly string[], rows: Fields[]): Uint8Array {
  return csv(
    [headers.join(","), ...rows.map((fields) => row(headers, fields))].join(
      "\n",
    ),
  );
}

function execution(fields: Fields): Fields {
  return { LevelOfDetail: "EXECUTION", ...fields };
}

